<script setup>
import {nacosValueType} from '../../delivery-editor/nacosValue.js'

import {nextTick, ref} from 'vue';

import HelpTip from '../../shared/components/HelpTip.vue';

const props=defineProps({model:{type:Object,required:true},disabled:Boolean});
const entries=ref(null);
async function addEntry(){props.model.entries.push({key:'',value:'',action:'set'});await nextTick();const row=entries.value?.querySelector('.config-entry:last-of-type');if(!row)return;row.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});focusControl(row.querySelector('input'),{preventScroll:true})}

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {focusControl} from '../../shared/focusControl.js'



import {Button,Field,FieldLabel,Input,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><div class="nacos-fields"><div class="nacos-location"><Field data-field="data_id"><FieldLabel as="div">Data ID（默认，可选）</FieldLabel><Input v-model="model.data_id" :disabled="disabled||!!model.restore" placeholder="优先使用目标环境绑定的 Data ID"/></Field><Field data-field="group"><FieldLabel as="div">默认 Group</FieldLabel><Input v-model="model.group" :disabled="disabled||!!model.restore"/></Field><Field data-field="format"><FieldLabel as="div">格式</FieldLabel><OptionPicker v-model="model.format" :options="['yaml','properties','json']" :disabled="disabled||!!model.restore" :style="{width:'100%',maxWidth:'100%'}"/></Field></div><div class="target-note"><span>环境绑定可覆盖默认值，执行前预览最终目标。</span><HelpTip align="right" :text="model.format==='properties'?'保存不发布；就绪后选择环境预览，再审核执行。properties 值按原文保存，只修改已有文档的配置项。请勿粘贴生产密钥。':'保存不发布；就绪后选择环境预览，再审核执行。YAML/JSON 的点表示层级；true、123、null 是对应类型，字符串可用双引号。只支持已有文档、标量配置项；请勿粘贴生产密钥。'"/></div><section ref="entries" data-field="entries" aria-label="配置项编辑" class="nacos-entries"><div class="entry-tools"><strong>配置项</strong><Button v-if="!disabled&&!model.restore" @click="addEntry" variant="outline" size="sm" type="button">＋ 配置项</Button></div><div aria-hidden="true" class="entry-columns"><span>配置项</span><span>操作</span><span>期望值</span><span></span></div><div v-for="(entry,i) in model.entries" :key="i" :data-entry-index="i" role="group" :aria-label="'配置项 '+(i+1)" class="config-entry"><div data-field="key"><Input v-model="entry.key" placeholder="配置项，例如 feature.enabled" :disabled="disabled||!!model.restore" v-bind="{&quot;aria-label&quot;:('第 '+(i+1)+' 个配置项名称')}"/></div><div data-field="action"><OptionPicker v-model="entry.action" :aria-label="'第 '+(i+1)+' 个配置项操作'" :options="[{value:'set',label:'设置值'},{value:'delete',label:'删除项'}]" :disabled="disabled||!!model.restore" :style="{width:'100%',maxWidth:'100%'}"/></div><div data-field="value"><Textarea v-model="entry.value" placeholder="期望值" :disabled="disabled||!!model.restore||entry.action==='delete'" v-bind="{&quot;aria-label&quot;:('第 '+(i+1)+' 个配置项期望值')}" :rows="({minRows:1,maxRows:6}).minRows||4"/><span class="text-xs text-muted-foreground" aria-live="polite">{{nacosValueType(entry.value,model.format,entry.action)}}</span></div><Button v-if="!disabled&&!model.restore" :aria-label="'删除第 '+(i+1)+' 个配置项'" @click="model.entries.splice(i,1)" variant="ghost" size="default" type="button">删除项</Button></div></section><p v-if="model.restore" class="restore-note">恢复草稿引用历史完整快照，配置项只读；执行前重新预览审核，当前文档变化会阻止恢复。</p></div></template>
